const buildAed2Template = (incident: Incident) => `<table style="background:#F2F2F2;border-collapse:collapse;width:100%;font-family:'Segoe UI',sans-serif;font-size:12px"><tbody>
<tr><td rowspan="3" style="padding:8px;font-size:20px;color:#000;letter-spacing:-0.5px">Azure Monitoring Alert</td><td style="background:#0070C0;color:#fff;padding:8px;width:110px">INCIDENT ID</td><td style="padding:8px">${incident.id}</td></tr>
<tr><td style="background:#0070C0;color:#fff;padding:8px">STATUS</td><td style="padding:8px">${incident.status.toUpperCase().includes('MITIGAT') ? 'MITIGATED' : 'ACTIVE'}</td></tr>
<tr><td style="background:#0070C0;color:#fff;padding:8px">SEVERITY</td><td style="padding:8px">${incident.severity}</td></tr>
<tr><td colspan="3" style="background:#0070C0;color:#fff;padding:8px;font-size:14px">ISSUE DEFINITION</td></tr>
<tr><td colspan="3" style="padding:8px">Our monitoring has detected an anomaly on the below resource.<br>Resource: ${incident.service} (${incident.region})<br>Customer: ${incident.customer}</td></tr>
<tr><td colspan="3" style="background:#0070C0;color:#fff;padding:8px;font-size:14px">INVESTIGATION</td></tr>
<tr><td colspan="3" style="padding:8px">We are currently investigating the issue. Will get back to you shortly with an update.</td></tr>
<tr><td colspan="3" style="background:#0070C0;color:#fff;padding:8px;font-size:14px">NEXT STEPS</td></tr>
<tr><td colspan="3" style="padding:8px"><strong>Action on Microsoft:</strong><ul><li>We are currently monitoring the resource and will share updates/next steps soon.</li></ul><strong>Action on You:</strong><ul><li>If you are experiencing issues with this resource, then please <strong>REPLY-ALL</strong> to this email and<ul><li>Share the impact details.</li><li>If the issue is critical then please create a support request (SR) with an appropriate severity and include the SR number in your reply.</li><li>Please do not forget to include the incident ID in the support request.</li></ul></li></ul></td></tr>
</tbody></table>`

const buildTemplate = (name: string, incident: Incident) => name === 'AED2' ? buildAed2Template(incident) : '<p>Issue summary</p><p>Current impact</p><p>Mitigation</p><p>Next update ETA</p>'

