const buildAed3Template = (incident: Incident, stage: string, issueType: string) => {
  if (issueType === 'Availability') return AED3_AVAILABILITY_TEMPLATES[stage] ?? ''
  if (issueType === 'Capacity') return AED3_CAPACITY_TEMPLATES[stage] ?? ''
  const stageBody: Record<string, string> = {
    Initial: `<p>We are aware of a${issueType === 'Availability' ? 'n availability' : ' capacity'} issue affecting ${incident.service} in ${incident.region} and are investigating.</p>`,
    Update: `<p>We continue to investigate the ${issueType.toLowerCase()} issue affecting ${incident.service}. An update will follow shortly.</p>`,
    Resolved: `<p>The ${issueType.toLowerCase()} issue affecting ${incident.service} has been resolved. We apologize for any inconvenience caused.</p>`,
    Onetime: `<p>This is an on-time scheduled update regarding the ${issueType.toLowerCase()} of ${incident.service} in ${incident.region}.</p>`,
  }
  return stageBody[stage] ?? ''
}

export default function DashboardPage() {
  const incidents = useSelector((state: RootState) => state.incidents)
  const dispatch = useDispatch()
  const [searchInput, setSearchInput] = useState('')
  const [searched, setSearched] = useState(false)
  const [incidentId, setIncidentId] = useState('')
  const [body, setBody] = useState('')
  const [templateName, setTemplateName] = useState('')
  const [aed3Stage, setAed3Stage] = useState('')
  const [aed3IssueType, setAed3IssueType] = useState('')
  const editorRef = useRef<HTMLDivElement>(null)
  const incident = incidents.find((item) => item.id === incidentId)

  const runSearch = () => {
    const term = searchInput.trim().toUpperCase()
    const match = incidents.find((item) => item.id.toUpperCase().includes(term))
    setIncidentId(match?.id ?? '')
    setBody(match?.draftBody ?? '')
    if (editorRef.current) editorRef.current.innerHTML = match?.draftBody ?? ''
    setSearched(true)
  }
  const sendForApproval = () => {
    if (!incident) return
    dispatch(updateIncident({ id: incident.id, changes: { communication: 'Pending Shift Lead Approval', approvalStatus: 'Pending', draftBody: body, submittedBy: 'NK17', submittedTime: 'Just now' } }))
  }
  const format = (command: string) => { document.execCommand(command); setBody(editorRef.current?.innerHTML ?? body) }
  const applyTemplate = (name: string) => {
    setTemplateName(name)
    setAed3Stage('')
    setAed3IssueType('')
    if (name === 'AED3') { setBody(''); if (editorRef.current) editorRef.current.innerHTML = ''; return }
    if (!name || !incident) return
    const html = buildTemplate(name, incident)
    setBody(html)
    if (editorRef.current) editorRef.current.innerHTML = html
  }
  const applyAed3 = (stage: string, issueType: string) => {
    setAed3Stage(stage)
    setAed3IssueType(issueType)
    if (!stage || !issueType || !incident) return
    const html = buildAed3Template(incident, stage, issueType)
    setBody(html)
    if (editorRef.current) editorRef.current.innerHTML = html
  }

  return <section className="page-section fade-in">
    <div className="page-heading"><div className="dashboard-search"><span>Incident ID</span><div className="search-box"><Search size={17} /><input id="incident-search-input" name="incidentSearch" value={searchInput} onChange={(event) => setSearchInput(event.target.value)} onKeyDown={(event) => { if (event.key === 'Enter') runSearch() }} placeholder="Search incidence id" /></div><button className="primary-button" onClick={runSearch}>Submit</button></div></div>
    {searched && (incident ? <>
      <div className="table-card"><div className="table-caption"><strong>Incident details</strong></div><div className="table-scroll"><table><thead><tr><th>Incident ID</th><th>Region</th><th>Incident title</th><th>Severity</th><th>Customer name</th><th>Service / workload</th><th>Incident status</th><th>Communication status</th><th>Submitted by / time</th><th>Approved by / time</th></tr></thead><tbody><tr><td><strong>{incident.id}</strong></td><td>{incident.region}</td><td><span>{incident.title}</span></td><td><Badge tone={incident.severity === 'SEV 1' ? 'sev-1' : incident.severity === 'SEV 2' ? 'sev-2' : 'sev-3'}>{incident.severity}</Badge></td><td>{incident.customer}</td><td>{incident.service}</td><td>{incident.status}</td><td>{incident.communication === 'Pending Shift Lead Approval' ? <Badge tone="pending-shift-lead-approval">Pending Shift Lead Approval</Badge> : <Badge tone={incident.communication.toLowerCase().replaceAll(' ', '-')}>{incident.communication}</Badge>}</td><td>{incident.submittedBy ? <><strong>{incident.submittedBy}</strong><span>{incident.submittedTime}</span></> : <span>Not submitted</span>}</td><td>{incident.approvedBy ? <><strong>{incident.approvedBy}</strong><span>{incident.approvedTime}</span></> : <span>Not approved</span>}</td></tr></tbody></table></div></div>
      <div className="section-card"><div className="card-heading"><div className="card-heading-text"><h2>Communication draft</h2></div><div className="template-search-group"><div className="template-search"><span>Use a template</span><div className="filter-select"><Filter size={15} /><select id="template-select" name="template" value={templateName} onChange={(event) => applyTemplate(event.target.value)}><option value="">Select template</option><option value="AED2">AED2</option><option value="AED3">AED3</option></select></div></div>{templateName === 'AED3' && <div className="template-search-row"><div className="template-search"><span>Communication Type</span><div className="filter-select"><Filter size={15} /><select id="aed3-stage-select" name="aed3Stage" value={aed3Stage} onChange={(event) => applyAed3(event.target.value, aed3IssueType)}><option value="">Select stage</option>{AED3_STAGES.map((stage) => <option key={stage} value={stage}>{stage}</option>)}</select></div></div><div className="template-search"><span>Issue Type</span><div className="filter-select"><Filter size={15} /><select id="aed3-issue-type-select" name="aed3IssueType" value={aed3IssueType} onChange={(event) => applyAed3(aed3Stage, event.target.value)}><option value="">Select issue type</option>{AED3_ISSUE_TYPES.map((type) => <option key={type} value={type}>{type}</option>)}</select></div></div></div>}</div></div><div className="editor-toolbar"><button title="Bold" onMouseDown={(event) => event.preventDefault()} onClick={() => format('bold')}><Bold size={15} /></button><button title="Italic" onMouseDown={(event) => event.preventDefault()} onClick={() => format('italic')}><Italic size={15} /></button><button title="Underline" onMouseDown={(event) => event.preventDefault()} onClick={() => format('underline')}><Underline size={15} /></button><button title="Strikethrough" onMouseDown={(event) => event.preventDefault()} onClick={() => format('strikeThrough')}><Strikethrough size={15} /></button><button title="Align left" onMouseDown={(event) => event.preventDefault()} onClick={() => format('justifyLeft')}><AlignLeft size={15} /></button><button title="Align center" onMouseDown={(event) => event.preventDefault()} onClick={() => format('justifyCenter')}><AlignCenter size={15} /></button><button title="Align right" onMouseDown={(event) => event.preventDefault()} onClick={() => format('justifyRight')}><AlignRight size={15} /></button></div><div ref={editorRef} className="rich-editor" contentEditable suppressContentEditableWarning onInput={(event) => setBody(event.currentTarget.innerHTML)} /><div className="composer-actions"><button className="primary-button" onClick={sendForApproval}><Send size={16} /> Send for approval</button></div></div>
    </> : <div className="empty-state"><p>No incident found for "{searchInput}"</p></div>)}
  </section>
}
